SELECT *, LEAD(quantity, 1) OVER (ORDER BY last_restock, id) AS next_quantity, LAST_VALUE(quantity, TRUE) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity, SUM(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity FROM inventory
